(function(E){ const x = E["exam-04"] = E["exam-04"] || {units:{}}; (x.units = x.units || {})["x04-r2"] = {"id":"x04-r2","patterns":["RA-mind","GT2-career","GT2-policy","PARA-research","PARA-rules"],"title":{"en":"Reading 2: Passage 2 / Section 2","tr":"Reading 2: Passage 2 / Section 2","fa":"Reading ۲: متن ۲ (Passage 2) / بخش ۲ (Section 2)"},"objective":{"en":"In this lesson you will learn to complete a summary from a box of ten words, decide YES, NO or NOT GIVEN about a writer’s views on education, and answer multiple-choice questions about the writer’s purpose.","tr":"Bu derste on kelimelik bir kutudan bir özeti tamamlamayı, yazarın eğitim hakkındaki görüşleri için YES, NO ya da NOT GIVEN kararı vermeyi ve yazarın amacıyla ilgili çoktan seçmeli soruları cevaplamayı öğreneceksin.","fa":"در این درس یاد می‌گیری یک خلاصه را از کادری ده‌کلمه‌ای کامل کنی، درباره‌ی نظرهای نویسنده درباره‌ی آموزش بین YES، NO و NOT GIVEN تصمیم بگیری و به سؤال‌های چندگزینه‌ای درباره‌ی هدف نویسنده جواب بدهی."},"objectiveGT":{"en":"In this lesson you will learn to answer short questions about a job guide with up to three words and/or a number, and to complete sentences about workplace rules with up to two words and/or a number.","tr":"Bu derste bir iş rehberiyle ilgili kısa soruları en fazla üç kelime ve/veya bir sayıyla cevaplamayı ve iş yeri kurallarıyla ilgili cümleleri en fazla iki kelime ve/veya bir sayıyla tamamlamayı öğreneceksin.","fa":"در این درس یاد می‌گیری به سؤال‌های کوتاه درباره‌ی یک راهنمای شغلی با حداکثر سه کلمه و/یا یک عدد جواب بدهی و جمله‌هایی درباره‌ی قانون‌های محل کار را با حداکثر دو کلمه و/یا یک عدد کامل کنی."},"sessions":[["explain"],["drill"],["exit"]],"explain":{"title":{"en":"Reading Passage 2: an argument about education","tr":"Reading Passage 2: eğitim üzerine bir tartışma","fa":"Reading Passage 2: استدلالی درباره‌ی آموزش"},"objective":{"en":"In this lesson you will learn to complete a summary from a box of ten words, decide YES, NO or NOT GIVEN about a writer’s views on education, and answer multiple-choice questions about the writer’s purpose.","tr":"Bu derste on kelimelik bir kutudan bir özeti tamamlamayı, yazarın eğitim hakkındaki görüşleri için YES, NO ya da NOT GIVEN kararı vermeyi ve yazarın amacıyla ilgili çoktan seçmeli soruları cevaplamayı öğreneceksin.","fa":"در این درس یاد می‌گیری یک خلاصه را از کادری ده‌کلمه‌ای کامل کنی، درباره‌ی نظرهای نویسنده درباره‌ی آموزش بین YES، NO و NOT GIVEN تصمیم بگیری و به سؤال‌های چندگزینه‌ای درباره‌ی هدف نویسنده جواب بدهی."},"stats":[{"label":{"en":"Questions","tr":"Soru","fa":"سؤال"},"value":"13"},{"label":{"en":"Time","tr":"Süre","fa":"زمان"},"value":{"en":"20 min","tr":"20 dk","fa":"۲۰ دقیقه"}},{"label":{"en":"Box","tr":"Kutu","fa":"کادر"},"value":"A-J"}],"context":{"eyebrow":{"en":"1 The context","tr":"1 Bağlam","fa":"۱ بافت"},"head":{"en":"This exam: learning in the language of home","tr":"Bu sınav: evin dilinde öğrenmek","fa":"این آزمون: آموختن به زبان خانه"},"intro":{"en":"Learning, the mind and society are among the most common Academic Reading subjects. An argument passage like this one reports research, answers objections and recommends a policy, so many questions ask what the writer believes.","tr":"Öğrenme, zihin ve toplum Academic Reading’in en yaygın konularındandır. Bunun gibi bir tartışma metni araştırmaları aktarır, itirazlara cevap verir ve bir politika önerir; bu yüzden birçok soru yazarın neye inandığını sorar.","fa":"یادگیری، ذهن و جامعه از رایج‌ترین موضوع‌های Academic Reading هستند. متنی استدلالی مثل این پژوهش‌ها را گزارش می‌کند، به مخالفت‌ها جواب می‌دهد و سیاستی را پیشنهاد می‌کند، پس خیلی از سؤال‌ها می‌پرسند نویسنده چه باور دارد."},"technique":{"en":"2 The technique","tr":"2 Teknik","fa":"۲ تکنیک"},"labels":{"asks":{"en":"What this part is about","tr":"Bu kısım ne hakkında","fa":"این بخش درباره‌ی چیست"},"fields":{"en":"Headings you will see","tr":"Göreceğin başlıklar","fa":"عنوان‌هایی که می‌بینی"},"words":{"en":"Words that carry the answers","tr":"Cevabı taşıyan kelimeler","fa":"کلمه‌هایی که جواب را می‌آورند"},"a":{"en":"On the paper","tr":"Kâğıtta","fa":"روی برگه"},"b":{"en":"What you hear or read","tr":"Duyduğun ya da okuduğun","fa":"چیزی که می‌شنوی یا می‌خوانی"},"traps":{"en":"Traps","tr":"Tuzaklar","fa":"دام‌ها"},"example":{"en":"Example","tr":"Örnek","fa":"نمونه"},"ideas":{"en":"Ideas","tr":"Fikirler","fa":"ایده‌ها"}},"cards":[{"id":"x04-r2-ctx","exam":true,"patterns":["RA-mind","PARA-research"],"often":{"pattern":"RA-mind","n":30,"of":120,"label":{"en":"Comes up often in the real exam: 30 of the last 120 passages","tr":"Gerçek sınavda sık çıkar: son 120 metnin 30’unda","fa":"در آزمون واقعی زیاد می‌آید: در ۳۰ متن از ۱۲۰ متنِ اخیر"}},"title":{"en":"Which language should children learn in?","tr":"Çocuklar hangi dilde öğrenmeli?","fa":"بچه‌ها به چه زبانی باید درس بخوانند؟"},"asks":{"en":"An argument about education: the writer explains why many rural children are taught in a language they do not speak, reviews the research, deals with practical problems and parents’ objections, and recommends a solution.","tr":"Eğitim üzerine bir tartışma yazısı: yazar birçok kırsal çocuğun neden konuşmadığı bir dilde eğitim aldığını açıklıyor, araştırmaları gözden geçiriyor, pratik sorunları ve ebeveynlerin itirazlarını ele alıyor ve bir çözüm öneriyor.","fa":"استدلالی درباره‌ی آموزش: نویسنده توضیح می‌دهد چرا خیلی از بچه‌های روستایی به زبانی درس می‌خوانند که بلد نیستند، پژوهش‌ها را مرور می‌کند، به مشکل‌های عملی و مخالفت والدین می‌پردازد و راه‌حلی پیشنهاد می‌کند."},"fields":["The problem","The old approach","Research findings","Other benefits","Practical problems","Parents’ views","The best way to change"],"words":[{"a":"mother tongue","b":"the language of home","tr":"ana dil","fa":"زبان مادری"},{"a":"have access to","b":"be able to get or use","tr":"... erişimi olmak","fa":"دسترسی داشتن به"},{"a":"pick up","b":"learn without lessons","tr":"kendiliğinden öğrenmek","fa":"خودبه‌خود یاد گرفتن"},{"a":"transfer","b":"move from one area to another","tr":"aktarmak","fa":"منتقل کردن"},{"a":"fall behind","b":"make slower progress than others","tr":"geride kalmak","fa":"عقب افتادن"},{"a":"involved","b":"taking part / interested","tr":"katılımcı, ilgili","fa":"درگیر، مشارکت‌کننده"},{"a":"shortage","b":"not enough","tr":"kıtlık, eksiklik","fa":"کمبود"},{"a":"recruit","b":"find and employ","tr":"işe almak","fa":"به کار گرفتن"},{"a":"dismiss","b":"refuse to take seriously","tr":"önemsememek","fa":"جدی نگرفتن"},{"a":"a misunderstanding","b":"a wrong idea","tr":"yanlış anlama","fa":"سوءتفاهم"},{"a":"gradually","b":"step by step","tr":"yavaş yavaş","fa":"کم‌کم"},{"a":"a firm foundation","b":"a strong base","tr":"sağlam bir temel","fa":"پایه‌ی محکم"}],"traps":[{"en":"The writer can understand a view and still disagree: \"I understand its attraction... however, it fails\". YES / NO depends on the writer’s final position.","tr":"Yazar bir görüşü anlayıp yine de katılmayabilir: \"Çekiciliğini anlıyorum... ancak başarısız oluyor\". YES / NO yazarın son tutumuna bağlıdır.","fa":"نویسنده ممکن است نظری را بفهمد و باز هم مخالف باشد: «جذابیتش را می‌فهمم... اما شکست می‌خورد». YES / NO به موضع نهایی نویسنده بستگی دارد."},{"en":"In a summary with a box, the words in the box are often not the passage’s words. Choose by meaning and grammar, not by matching letters.","tr":"Kutulu bir özette kutudaki kelimeler çoğu zaman metnin kelimeleri değildir. Harf eşleştirerek değil, anlam ve dilbilgisiyle seç.","fa":"در خلاصه‌ی کادردار، کلمه‌های کادر اغلب همان کلمه‌های متن نیستند. با معنی و دستور زبان انتخاب کن، نه با شباهت ظاهری."}],"example":{"text":"\"Homework has its defenders, and I can see why. Even so, I believe that for young children it does more harm than good.\"","item":"Statement: Homework is good for young children. YES, NO or NOT GIVEN?","answer":"NO","why":{"en":"\"I can see why\" shows understanding, but the writer’s position is \"more harm than good\".","tr":"\"Nedenini anlıyorum\" anlayış gösterir ama yazarın tutumu \"yararından çok zarar\".","fa":"«می‌فهمم چرا» نشانه‌ی درک است، اما موضع نویسنده «ضررش بیشتر از فایده‌اش» است."}}},{"id":"RA-mind-arg","ctx":["RA-mind"],"title":{"en":"Arguments about learning and society","tr":"Öğrenme ve toplum üzerine tartışma yazıları","fa":"نوشته‌های استدلالی درباره‌ی یادگیری و جامعه"},"asks":{"en":"An argument about education, behaviour or society: should children learn handwriting, does praise help, can wisdom be learned. The writer reports other views and gives their own; multiple choice and summaries follow the argument.","tr":"Eğitim, davranış ya da toplum üzerine bir tartışma yazısı: çocuklar el yazısı öğrenmeli mi, övgü işe yarar mı, bilgelik öğrenilebilir mi. Yazar başka görüşleri aktarır ve kendi görüşünü verir; çoktan seçmeli sorular ve özetler tartışmanın akışını izler.","fa":"نوشته‌ای استدلالی درباره‌ی آموزش، رفتار یا جامعه: آیا بچه‌ها باید دست‌خط یاد بگیرند، آیا تعریف کردن کمک می‌کند، آیا خرد یادگرفتنی است. نویسنده نظرهای دیگران را نقل می‌کند و نظر خودش را می‌دهد؛ چندگزینه‌ای و خلاصه‌ها مسیر استدلال را دنبال می‌کنند."},"fields":["The writer agrees with the government’s view. (YES / NO / NOT GIVEN)","What does the writer say about earlier research?","The writer’s purpose in the final paragraph is to...","Summary: many teachers ___ the importance of..."],"words":[{"a":"in favour of","b":"supports / argues for","tr":"lehinde","fa":"موافقِ"},{"a":"against","b":"opposes / objects to","tr":"aleyhinde","fa":"مخالفِ"},{"a":"misguided","b":"wrong / based on a mistake","tr":"yanlış temelli","fa":"نادرست"},{"a":"reasonable","b":"fair / makes sense","tr":"makul","fa":"منطقی"},{"a":"exaggerate","b":"overstate / make it sound bigger","tr":"abartmak","fa":"اغراق کردن"},{"a":"widely held","b":"many people believe","tr":"yaygın","fa":"رایج"},{"a":"it remains to be seen","b":"we do not know yet","tr":"henüz belli değil","fa":"هنوز معلوم نیست"},{"a":"evidence suggests","b":"research indicates","tr":"kanıtlar gösteriyor ki","fa":"شواهد نشان می‌دهد"},{"a":"sceptical","b":"doubtful","tr":"şüpheci","fa":"تردیدآمیز"},{"a":"a balanced view","b":"both sides","tr":"dengeli bir bakış","fa":"دیدگاه متعادل"},{"a":"ultimately","b":"in the end","tr":"sonuç olarak","fa":"در نهایت"},{"a":"rightly","b":"correctly / with good reason","tr":"haklı olarak","fa":"به‌درستی"}],"traps":[{"en":"The writer’s opinion often sits in one word: \"rightly\", \"wrongly\", \"surprisingly\". Watch the adverbs.","tr":"Yazarın görüşü çoğu zaman tek bir kelimededir: \"rightly\", \"wrongly\", \"surprisingly\". Zarflara dikkat et.","fa":"نظر نویسنده اغلب در یک کلمه است: «rightly»، «wrongly»، «surprisingly». به قیدها دقت کن."},{"en":"Summary with a box: the words in the box are paraphrases. Choose by meaning and by grammar.","tr":"Kutulu özet: kutudaki kelimeler başka ifadelerdir. Hem anlama hem dilbilgisine göre seç.","fa":"خلاصه با جعبه: کلمه‌های جعبه هم‌معنی‌اند. هم بر اساس معنی و هم بر اساس دستور انتخاب کن."}],"example":{"text":"Praising children for being clever is widely recommended. I believe this advice is misguided: children praised for their intelligence often avoid difficult tasks, in case they fail.","item":"Statement: The writer agrees that children should be praised for being clever.  (YES / NO / NOT GIVEN)","answer":"NO","why":{"en":"The advice is \"widely recommended\", but the writer calls it \"misguided\": NO.","tr":"Tavsiye \"yaygın olarak öneriliyor\" ama yazar ona \"yanlış\" diyor: NO.","fa":"این توصیه «رایج است»، ولی نویسنده آن را «نادرست» می‌داند: NO."}},"track":"academic","general":true,"patterns":["RA-mind"],"often":{"pattern":"RA-mind","n":30,"of":120,"label":{"en":"Comes up often in the real exam: 30 of the last 120 passages","tr":"Gerçek sınavda sık çıkar: son 120 metnin 30’unda","fa":"در آزمون واقعی زیاد می‌آید: در ۳۰ متن از ۱۲۰ متنِ اخیر"}}}]},"points":[{"eyebrow":{"en":"In the exam","tr":"Sınavda","fa":"در آزمون"},"head":{"en":"A summary, statements, then purpose","tr":"Bir özet, ifadeler, sonra amaç","fa":"یک خلاصه، جمله‌ها، بعد هدف"},"body":{"en":"Questions 14-19: complete a summary with words from a box of ten, A-J; four are not used. Questions 20-23: YES, NO or NOT GIVEN about the writer’s views. Questions 24-26: multiple choice, A-D, often about why the writer mentions something.","tr":"Soru 14-19: on kelimelik kutudan (A-J) bir özeti tamamla; dördü kullanılmaz. Soru 20-23: yazarın görüşleri hakkında YES, NO ya da NOT GIVEN. Soru 24-26: çoktan seçmeli, A-D; çoğu zaman yazarın bir şeyden neden söz ettiğiyle ilgili.","fa":"سؤال‌های ۱۴ تا ۱۹: خلاصه‌ای را با کلمه‌های یک کادر ده‌تایی (A تا J) کامل کن؛ چهار تا استفاده نمی‌شوند. سؤال‌های ۲۰ تا ۲۳: YES، NO یا NOT GIVEN درباره‌ی نظرهای نویسنده. سؤال‌های ۲۴ تا ۲۶: چندگزینه‌ای، A تا D، اغلب درباره‌ی اینکه نویسنده چرا از چیزی اسم می‌برد."}},{"eyebrow":{"en":"The method","tr":"Yöntem","fa":"روش"},"head":{"en":"Grammar first, then meaning","tr":"Önce dilbilgisi, sonra anlam","fa":"اول دستور، بعد معنی"},"steps":[{"en":"For each summary gap, decide what fits the grammar: an adverb after \"more\", a noun after \"of\", a verb after \"often\".","tr":"Her özet boşluğu için dilbilgisine neyin uyduğuna karar ver: \"more\"dan sonra zarf, \"of\"tan sonra isim, \"often\"dan sonra fiil.","fa":"برای هر جای خالی خلاصه ببین چه چیزی از نظر دستوری جا می‌شود: قید بعد از «more»، اسم بعد از «of»، فعل بعد از «often»."},{"en":"Find the part of the passage the summary covers and choose the box word that means the same.","tr":"Özetin kapsadığı metin bölümünü bul ve aynı anlama gelen kutu kelimesini seç.","fa":"بخشی از متن را که خلاصه پوشش می‌دهد پیدا کن و کلمه‌ای از کادر را انتخاب کن که همان معنی را دارد."},{"en":"For \"why does the writer mention...\", ask what point the example supports.","tr":"\"Yazar neden ... söz ediyor\" için örneğin hangi noktayı desteklediğini sor.","fa":"برای «چرا نویسنده از ... حرف می‌زند»، بپرس آن مثال از کدام نکته پشتیبانی می‌کند."}]},{"eyebrow":{"en":"The trap","tr":"Tuzak","fa":"دام"},"head":{"en":"Understanding is not agreeing","tr":"Anlamak, katılmak değildir","fa":"فهمیدن یعنی موافق بودن نیست"},"body":{"en":"Writers often show they understand the other side (\"I can see the appeal\", \"this concern is natural\") before saying it is wrong. Read on to the \"however\" or \"but\" before you decide YES or NO.","tr":"Yazarlar bir şeyin yanlış olduğunu söylemeden önce çoğu zaman karşı tarafı anladıklarını gösterir (\"cazibesini görebiliyorum\", \"bu endişe doğal\"). YES ya da NO’ya karar vermeden önce \"however\" ya da \"but\"a kadar oku.","fa":"نویسنده‌ها اغلب قبل از اینکه بگویند چیزی غلط است نشان می‌دهند طرف مقابل را می‌فهمند («جذابیتش را می‌بینم»، «این نگرانی طبیعی است»). قبل از تصمیم درباره‌ی YES یا NO تا «however» یا «but» بخوان."}}],"example":{"eyebrow":{"en":"Worked example","tr":"Çözümlü örnek","fa":"مثال حل‌شده"},"head":{"en":"One summary gap, step by step","tr":"Bir özet boşluğu, adım adım","fa":"یک جای خالی خلاصه، قدم به قدم"},"instruction":"Complete the summary using the box: A cheaper  B slower  C safer","text":"\"Electric buses cost more to buy, but because they need fewer repairs and no fuel, they cost far less to run.\"","item":"Electric buses are ___ to run than diesel buses.","answer":"A","walk":[{"en":"\"___ to run than\" needs a comparative adjective.","tr":"\"___ to run than\" bir karşılaştırma sıfatı ister.","fa":"«___ to run than» صفت تفضیلی می‌خواهد."},{"en":"The passage: they \"cost far less to run\".","tr":"Metin: \"cost far less to run\" (çalıştırma maliyetleri çok daha düşük).","fa":"متن: «cost far less to run» (هزینه‌ی کارکردشان خیلی کمتر است)."},{"en":"\"Cost less\" = cheaper: A.","tr":"\"Cost less\" (daha az maliyetli) = \"cheaper\": A.","fa":"«cost less» (هزینه‌ی کمتر) یعنی «cheaper»: A."}]},"quick":{"prompt":"Text: \"Many parents want early English lessons, and I can see why. But starting too early often slows learning.\" Statement: \"English lessons should start as early as possible.\" YES, NO or NOT GIVEN?","options":["NO","YES","NOT GIVEN"],"correct":0,"why":{"en":"\"I can see why\" shows understanding, but the writer says starting too early \"slows learning\".","tr":"\"Nedenini anlıyorum\" anlayış gösterir ama yazar çok erken başlamanın \"öğrenmeyi yavaşlattığını\" söylüyor.","fa":"«می‌فهمم چرا» نشانه‌ی درک است، اما نویسنده می‌گوید شروعِ خیلی زود «یادگیری را کند می‌کند»."}},"remember":{"en":"Choose box words by grammar and meaning, and read past \"I understand\" to the writer’s real view.","tr":"Kutu kelimelerini dilbilgisi ve anlama göre seç ve \"I understand\"ın ötesine, yazarın gerçek görüşüne kadar oku.","fa":"کلمه‌های کادر را با دستور و معنی انتخاب کن و از «I understand» جلوتر تا نظر واقعی نویسنده بخوان."},"type":"explain","id":"c-x04-r2-e","course":"ielts-exams","exam":"exam-04","unit":"x04-r2"},"drill":{"type":"drill","skill":"reading","part":"Academic Reading Passage 2","title":{"en":"Learning in the language of home","tr":"Evin dilinde öğrenmek","fa":"آموختن به زبان خانه"},"timed":20,"ctx":["RA-mind"],"intro":"You should spend about 20 minutes on Questions 14-26, which are based on Reading Passage 2 below.","passage":"Learning in the language of home\n\nImagine starting school at the age of six and finding that your teacher speaks a language you have never heard. The books, the instructions and the tests are all in that language, and nobody explains anything in the language you speak at home. For millions of children this is not an imaginary situation but their first experience of education. UNESCO has estimated that around forty per cent of the world's population does not have access to education in a language they speak or understand. The problem is especially common in rural areas, where children may grow up speaking one of several local languages that are rarely used in schools.\n\nFor a long time, the usual response was to say that children would simply pick up the language of the classroom. Young children, after all, learn languages easily. This \"sink or swim\" approach still has many supporters, and I understand its attraction: it is cheap, it requires only one set of books and it seems to prepare children for a world in which the national or a global language is needed. In my view, however, it fails most of the children it is meant to help.\n\nThe research evidence on this point is now very strong. Children who begin school in their home language learn to read more quickly, because they are only learning one new thing, how letters represent sounds, rather than two at the same time. Crucially, reading skills learned in one language can later be transferred to another. A child who can already read in her first language has a much easier task when she meets a second one. By contrast, pupils who are taught from the start in an unfamiliar language are more likely to fall behind, to repeat school years and to leave school early.\n\nThe benefits go beyond reading. When lessons are given in the language of the home, parents can understand what their children are learning, help with homework and talk to teachers. In several programmes, schools that changed to the home language reported that parents became far more involved in their children's education. Children themselves tend to participate more in class when they can understand and answer questions, instead of sitting in silence, and teachers find it much easier to see who has understood a lesson and who needs more help.\n\nWhy, then, is mother-tongue teaching not more common? One reason is practical. Many countries have dozens or even hundreds of languages, and finding enough trained teachers who speak each one is difficult, especially in remote villages. There is also a serious shortage of materials: in many local languages, there are very few books, and some languages have only recently been written down at all. A single rural classroom may contain children who speak three or four different home languages.\n\nThese difficulties are real, but they are not impossible to overcome. Teachers can be recruited from the communities they serve and trained locally, and books can be produced cheaply once a spelling system exists. Where several languages are spoken in one class, children can be grouped for reading lessons. None of this is easy, but it is far cheaper in the long run than the cost of children repeating years or leaving school unable to read.\n\nA second obstacle is opposition from parents, which may seem surprising. Many families in poor rural areas want their children to learn the national language, or a global one such as English, as early as possible, because they see it as the key to a better job. This wish is entirely understandable, and it would be wrong to dismiss it. But it rests on a misunderstanding. The aim of mother-tongue teaching is not to keep children away from other languages, but to give them a firm foundation from which to learn them.\n\nWhat matters most is how the change to a second language is made. Programmes that switch suddenly to the national language after only one year often lose the advantages of the early years. The most successful ones introduce the second language gradually, first as a subject and then, over several years, as a language of teaching, while continuing to use the home language alongside it.\n\nLanguage is not the only reason why children in poor rural areas struggle at school, and changing it will not solve every problem. But it is hard to think of a reform that costs so little and does so much. A child who understands her teacher on the first day of school has already been given something that many children never receive.","groups":[{"instruction":"Questions 14-19. Complete the summary using the list of words, A-J, below. Write the correct letter, A-J, in boxes 14-19 on your answer sheet.","qtype":"summary-box","summaryTitle":"What the research shows","bank":["A confident","B involved","C materials","D quickly","E repeat","F reluctant","G skills","H slowly","I teachers","J wealthier"],"questions":[{"n":14,"kind":"match","prompt":"Children who start school in their home language learn to read more ___,","correct":3,"evidence":"learn to read more quickly","why":{"en":"\"Learn to read more quickly\": quickly (D). \"Slowly\" (H) is the opposite.","tr":"\"Daha hızlı okumayı öğrenirler\": quickly (D). \"Slowly\" (H) tersi.","fa":"«سریع‌تر خواندن را یاد می‌گیرند»: quickly (D). «slowly» (H) برعکسش است."},"trap":["TR-samewords","PARA-research"]},{"n":15,"kind":"match","prompt":"and the reading ___ they develop can later be used in another language.","correct":6,"evidence":"reading skills learned in one language can later be transferred to another","why":{"en":"\"Reading skills... can later be transferred to another\": skills (G).","tr":"\"Okuma becerileri... daha sonra başka bir dile aktarılabilir\": skills (G).","fa":"«مهارت‌های خواندن... بعداً به زبان دیگری منتقل می‌شوند»: skills (G)."},"trap":["TR-paraphrase"]},{"n":16,"kind":"match","prompt":"Pupils taught only in an unfamiliar language are more likely to ___ school years.","correct":4,"evidence":"to repeat school years","why":{"en":"\"More likely to fall behind, to repeat school years\": repeat (E).","tr":"\"Geride kalma, sınıf tekrarlama olasılıkları daha yüksek\": repeat (E).","fa":"«احتمال عقب افتادن و تکرار پایه‌ها بیشتر است»: repeat (E)."},"trap":["TR-paraphrase"]},{"n":17,"kind":"match","prompt":"Parents also tend to become more ___ in their children’s education.","correct":1,"evidence":"parents became far more involved","why":{"en":"\"Parents became far more involved\": involved (B). \"Reluctant\" (F) means the opposite.","tr":"\"Ebeveynler çok daha fazla ilgilenmeye başladı\": involved (B). \"Reluctant\" (F) tersini anlatır.","fa":"«والدین خیلی بیشتر درگیر شدند»: involved (B). «reluctant» (F) معنی برعکس دارد."},"trap":["TR-paraphrase"]},{"n":18,"kind":"match","prompt":"The main practical problems are a lack of trained ___ who speak local languages","correct":8,"evidence":"finding enough trained teachers who speak each one is difficult","why":{"en":"\"Finding enough trained teachers who speak each one is difficult\": teachers (I).","tr":"\"Her birini konuşan yeterli eğitimli öğretmen bulmak zor\": teachers (I).","fa":"«پیدا کردن معلم‌های آموزش‌دیده‌ی کافی که هر کدام را بلد باشند سخت است»: teachers (I)."},"trap":["TR-paraphrase"]},{"n":19,"kind":"match","prompt":"and a shortage of ___ such as books.","correct":2,"evidence":"There is also a serious shortage of materials","why":{"en":"\"A serious shortage of materials: ... very few books\": materials (C).","tr":"\"Ciddi bir materyal eksikliği: ... çok az kitap\": materials (C).","fa":"«کمبود جدی منابع آموزشی: ... کتاب خیلی کم»: materials (C)."},"trap":["TR-paraphrase"]}]},{"instruction":"Questions 20-23. Do the following statements agree with the views of the writer in Reading Passage 2? In boxes 20-23 on your answer sheet, write YES if the statement agrees with the views of the writer, NO if the statement contradicts the views of the writer, NOT GIVEN if it is impossible to say what the writer thinks about this.","qtype":"ynng","questions":[{"n":20,"kind":"ynng","prompt":"The \"sink or swim\" approach is successful for most children.","correct":"NO","evidence":"it fails most of the children it is meant to help","why":{"en":"The writer understands its attraction, \"however, it fails most of the children it is meant to help\".","tr":"Yazar çekiciliğini anlıyor \"ancak yardım etmesi gereken çocukların çoğunda başarısız oluyor\".","fa":"نویسنده جذابیتش را می‌فهمد، «اما برای بیشتر بچه‌هایی که قرار است کمکشان کند شکست می‌خورد»."},"trap":["TR-whosevoice","TR-NGvsF"]},{"n":21,"kind":"ynng","prompt":"It is reasonable for parents to want their children to learn a global language.","correct":"YES","evidence":"This wish is entirely understandable","why":{"en":"\"This wish is entirely understandable, and it would be wrong to dismiss it.\"","tr":"\"Bu istek tamamen anlaşılır ve onu önemsememek yanlış olur.\"","fa":"«این خواسته کاملاً قابل‌درک است و نادیده گرفتنش اشتباه است»."},"trap":["TR-paraphrase"]},{"n":22,"kind":"ynng","prompt":"Teachers who speak local languages should be paid more than other teachers.","correct":"NOT GIVEN","evidence":"Teachers can be recruited from the communities they serve","why":{"en":"The writer discusses recruiting and training teachers, not their pay.","tr":"Yazar öğretmenlerin işe alınmasını ve eğitimini tartışıyor, maaşlarını değil.","fa":"نویسنده درباره‌ی جذب و آموزش معلم‌ها حرف می‌زند، نه حقوقشان."},"trap":["TR-NGvsF"]},{"n":23,"kind":"ynng","prompt":"The best approach is to change to the national language after the first year of school.","correct":"NO","evidence":"Programmes that switch suddenly to the national language after only one year often lose the advantages","why":{"en":"A sudden switch after one year \"often loses the advantages\"; the writer prefers a gradual change.","tr":"Bir yıl sonra ani geçiş \"çoğu zaman avantajları kaybettiriyor\"; yazar kademeli bir geçişi tercih ediyor.","fa":"تغییر ناگهانی بعد از یک سال «اغلب مزیت‌ها را از بین می‌برد»؛ نویسنده تغییر تدریجی را ترجیح می‌دهد."},"trap":["TR-whosevoice"]}]},{"instruction":"Questions 24-26. Choose the correct letter, A, B, C or D. Write the correct letter in boxes 24-26 on your answer sheet.","qtype":"mcq","questions":[{"n":24,"kind":"mcq","prompt":"The writer mentions the UNESCO estimate in order to show","options":["A that most children speak more than one language.","B how many people the problem affects.","C that rural schools have fewer teachers.","D that the problem is getting worse."],"correct":1,"evidence":"UNESCO has estimated that around forty per cent","why":{"en":"\"Around forty per cent of the world’s population\" shows how widespread the problem is. Nothing is said about it getting worse.","tr":"\"Dünya nüfusunun yaklaşık yüzde kırkı\" sorunun ne kadar yaygın olduğunu gösteriyor. Kötüleştiğine dair bir şey yok.","fa":"«حدود چهل درصد جمعیت جهان» نشان می‌دهد مشکل چقدر گسترده است. چیزی درباره‌ی بدتر شدنش گفته نشده."},"trap":["TR-paraphrase","PARA-research"]},{"n":25,"kind":"mcq","prompt":"What does the writer suggest for classes in which several home languages are spoken?","options":["A All lessons should be in the national language.","B Extra teachers should be employed.","C Children could be put into groups for reading.","D Such classes should be divided into separate schools."],"correct":2,"evidence":"children can be grouped for reading lessons","why":{"en":"\"Where several languages are spoken in one class, children can be grouped for reading lessons.\"","tr":"\"Bir sınıfta birkaç dil konuşuluyorsa, çocuklar okuma dersleri için gruplara ayrılabilir.\"","fa":"«وقتی در یک کلاس چند زبان هست، می‌شود بچه‌ها را برای درس خواندن گروه‌بندی کرد»."},"trap":["TR-paraphrase"]},{"n":26,"kind":"mcq","prompt":"What is the writer’s main purpose?","options":["A to compare schools in several countries","B to describe the history of language teaching","C to explain why parents oppose new methods","D to argue that children should first be taught in their home language"],"correct":3,"evidence":"it is hard to think of a reform that costs so little and does so much","why":{"en":"The whole article argues for mother-tongue teaching, ending with \"a reform that costs so little and does so much\". Parents’ views are only one part.","tr":"Bütün yazı ana dilde eğitimi savunuyor ve \"bu kadar az maliyetle bu kadar çok şey yapan bir reform\" ile bitiyor. Ebeveynlerin görüşleri yalnızca bir bölüm.","fa":"کل مقاله از آموزش به زبان مادری دفاع می‌کند و با «اصلاحی که این‌قدر کم هزینه دارد و این‌قدر کار می‌کند» تمام می‌شود. نظر والدین فقط یک بخش است."},"trap":["TR-samewords"]}]}],"id":"c-x04-r2-d","course":"ielts-exams","exam":"exam-04","unit":"x04-r2"},"exit":{"type":"exit","items":[{"tests":"word","point":1,"prompt":"\"There is a shortage of trained staff.\" This means there are...","options":["too many trained staff","no staff at all","not enough trained staff"],"correct":2,"why":{"en":"A shortage = not enough of something.","tr":"Shortage = bir şeyin yeterince olmaması.","fa":"shortage یعنی کمبود، به اندازه‌ی کافی نبودن."}},{"tests":"paraphrase","point":1,"prompt":"Which phrase means \"be used in another area\"?","options":["be limited to","be transferred to","be replaced by"],"correct":1,"why":{"en":"Transferred to = moved to and used in another place.","tr":"Transferred to = başka bir yere aktarılıp orada kullanılmak.","fa":"transferred to یعنی به جای دیگری منتقل و آن‌جا استفاده شدن."}},{"tests":"method","point":2,"prompt":"Summary gap: \"the new seeds grew more ___\" with a box of words. What should you decide first?","options":["the kind of word that fits after \"more\"","which box word appears in the passage","the longest word in the box"],"correct":0,"why":{"en":"After \"grew more\" you need an adverb such as quickly or slowly; grammar narrows the choice.","tr":"\"Grew more\"den sonra quickly ya da slowly gibi bir zarf gerekir; dilbilgisi seçimi daraltır.","fa":"بعد از «grew more» قیدی مثل quickly یا slowly لازم است؛ دستور زبان انتخاب را محدود می‌کند."}},{"tests":"trap","point":3,"prompt":"Text: \"Some say the reform is too costly, and I understand why. Still, I believe it will save money in the end.\" Statement: \"The reform will save money.\" YES, NO or NOT GIVEN?","options":["NO","NOT GIVEN","YES"],"correct":2,"why":{"en":"\"I understand why\" shows understanding of the other view; the writer still believes it will save money.","tr":"\"Nedenini anlıyorum\" karşı görüşü anladığını gösterir; yazar yine de para tasarrufu sağlayacağına inanıyor.","fa":"«می‌فهمم چرا» نشانه‌ی درک نظر مقابل است؛ نویسنده باز هم باور دارد که پول صرفه‌جویی می‌شود."}},{"tests":"trap","point":2,"prompt":"An article about water shortages opens with the story of one farmer whose well has dried up. Why might the writer begin this way?","options":["to give the writer’s final conclusion","to make the problem feel real to the reader","to prove that earlier research was wrong"],"correct":1,"why":{"en":"One real case at the start makes a large problem feel personal; the argument comes later.","tr":"Başta anlatılan tek bir gerçek örnek, büyük bir sorunu kişisel hissettirir; asıl tartışma sonra gelir.","fa":"یک نمونه‌ی واقعی در شروع، مشکلی بزرگ را ملموس و شخصی می‌کند؛ استدلال اصلی بعداً می‌آید."}}],"id":"c-x04-r2-x","course":"ielts-exams","exam":"exam-04","unit":"x04-r2"},"gt":{"explain":{"title":{"en":"GT Reading Section 2: work guides","tr":"GT Reading Section 2: iş rehberleri","fa":"GT Reading Section 2: راهنماهای کاری"},"objective":{"en":"In this lesson you will learn to answer short questions about a job guide with up to three words and/or a number, and to complete sentences about workplace rules with up to two words and/or a number.","tr":"Bu derste bir iş rehberiyle ilgili kısa soruları en fazla üç kelime ve/veya bir sayıyla cevaplamayı ve iş yeri kurallarıyla ilgili cümleleri en fazla iki kelime ve/veya bir sayıyla tamamlamayı öğreneceksin.","fa":"در این درس یاد می‌گیری به سؤال‌های کوتاه درباره‌ی یک راهنمای شغلی با حداکثر سه کلمه و/یا یک عدد جواب بدهی و جمله‌هایی درباره‌ی قانون‌های محل کار را با حداکثر دو کلمه و/یا یک عدد کامل کنی."},"stats":[{"label":{"en":"Questions","tr":"Soru","fa":"سؤال"},"value":"13"},{"label":{"en":"Texts","tr":"Metin","fa":"متن"},"value":"2"},{"label":{"en":"Word limit","tr":"Kelime sınırı","fa":"سقف کلمه"},"value":{"en":"3 / 2 words + number","tr":"3 / 2 kelime + sayı","fa":"۳ / ۲ کلمه + عدد"}}],"context":{"eyebrow":{"en":"1 The context","tr":"1 Bağlam","fa":"۱ بافت"},"head":{"en":"This exam: summer work at a hotel","tr":"Bu sınav: bir otelde yaz işi","fa":"این آزمون: کار تابستانی در یک هتل"},"intro":{"en":"Section 2 always has two work texts. Job guides and staff rules are among the commonest: they are full of numbers, conditions and requirements, and the questions test them exactly.","tr":"Section 2’de her zaman iki iş metni vardır. İş rehberleri ve personel kuralları en yaygınlardandır: sayılar, koşullar ve gerekliliklerle doludur ve sorular bunları kesin biçimde ölçer.","fa":"Section 2 همیشه دو متن کاری دارد. راهنماهای شغلی و قانون‌های کارکنان از رایج‌ترین‌ها هستند: پر از عدد، شرط و الزام‌اند و سؤال‌ها همین‌ها را دقیق می‌سنجند."},"technique":{"en":"2 The technique","tr":"2 Teknik","fa":"۲ تکنیک"},"labels":{"asks":{"en":"What this part is about","tr":"Bu kısım ne hakkında","fa":"این بخش درباره‌ی چیست"},"fields":{"en":"Headings you will see","tr":"Göreceğin başlıklar","fa":"عنوان‌هایی که می‌بینی"},"words":{"en":"Words that carry the answers","tr":"Cevabı taşıyan kelimeler","fa":"کلمه‌هایی که جواب را می‌آورند"},"a":{"en":"On the paper","tr":"Kâğıtta","fa":"روی برگه"},"b":{"en":"What you hear or read","tr":"Duyduğun ya da okuduğun","fa":"چیزی که می‌شنوی یا می‌خوانی"},"traps":{"en":"Traps","tr":"Tuzaklar","fa":"دام‌ها"},"example":{"en":"Example","tr":"Örnek","fa":"نمونه"},"ideas":{"en":"Ideas","tr":"Fikirler","fa":"ایده‌ها"}},"cards":[{"id":"x04-r2gt-ctx","exam":true,"patterns":["GT2-career","GT2-policy","PARA-rules"],"often":{"pattern":"GT2-career","n":18,"of":55,"label":{"en":"Comes up often in the real exam: 18 of the last 55 texts","tr":"Gerçek sınavda sık çıkar: son 55 metnin 18’inde","fa":"در آزمون واقعی زیاد می‌آید: در ۱۸ متن از ۵۵ متنِ اخیر"}},"title":{"en":"Seasonal hotel work and leave rules","tr":"Mevsimlik otel işi ve izin kuralları","fa":"کار فصلی در هتل و قانون‌های مرخصی"},"asks":{"en":"Section 2 is about work. Here: a guide for people taking a summer job at a hotel, and the hotel’s rules for permanent staff who want to take holidays or are ill.","tr":"Section 2 iş hayatıyla ilgilidir. Burada: bir otelde yaz işi alan kişiler için bir rehber ve otelin, tatile çıkmak isteyen ya da hastalanan kadrolu personel için kuralları.","fa":"Section 2 درباره‌ی کار است. این‌جا: راهنمایی برای کسانی که کار تابستانی در یک هتل می‌گیرند و قانون‌های هتل برای کارکنان دائمی که می‌خواهند مرخصی بروند یا بیمار می‌شوند."},"fields":["Contract length","Requirements","Accommodation","Uniforms","Transport","Pay","Leave","Sickness"],"words":[{"a":"minimum","b":"at least / the shortest allowed","tr":"en az","fa":"حداقل"},{"a":"deducted from your pay","b":"taken out of your wages","tr":"maaşından kesilir","fa":"از حقوقت کم می‌شود"},{"a":"on site","b":"at the workplace","tr":"iş yerinde","fa":"در محل کار"},{"a":"fortnightly","b":"once every two weeks","tr":"iki haftada bir","fa":"هر دو هفته یک بار"},{"a":"entitled to","b":"have a right to","tr":"... hakkı olmak","fa":"حق داشتن"},{"a":"in proportion to","b":"according to how much","tr":"... oranında","fa":"به نسبتِ"},{"a":"in advance","b":"before","tr":"önceden","fa":"از قبل"},{"a":"carried over","b":"moved to next year","tr":"devredilmiş","fa":"به سال بعد منتقل‌شده"},{"a":"special circumstances","b":"unusual situations","tr":"özel durumlar","fa":"شرایط خاص"},{"a":"a doctor’s note","b":"a letter from a doctor","tr":"doktor raporu","fa":"گواهی پزشک"}],"traps":[{"en":"Short answers: \"a valid driving licence\" is four words if you copy \"a\". Leave out the article to stay within three.","tr":"Kısa cevaplar: \"a\"yı da kopyalarsan \"a valid driving licence\" dört kelimedir. Üçte kalmak için artikeli çıkar.","fa":"جواب‌های کوتاه: اگر «a» را هم کپی کنی، «a valid driving licence» چهار کلمه است. برای ماندن در سه کلمه حرف تعریف را حذف کن."},{"en":"A number can be written as a figure or a word: 5 or five. Both count as one word; copy the one in the text.","tr":"Bir sayı rakamla ya da kelimeyle yazılabilir: 5 ya da five. İkisi de tek kelime sayılır; metindekini kopyala.","fa":"عدد را می‌شود با رقم یا با حروف نوشت: 5 یا five. هر دو یک کلمه حساب می‌شوند؛ همانی را که در متن است کپی کن."}],"example":{"text":"\"Lockers can be rented from the main reception for £3 a week.\"","item":"Where can staff rent a locker? (NO MORE THAN THREE WORDS AND/OR A NUMBER)","answer":"the main reception","why":{"en":"Three words from the text answer \"where\".","tr":"Metinden üç kelime \"nerede\"yi cevaplıyor.","fa":"سه کلمه از متن به «کجا» جواب می‌دهند."}}},{"id":"GT2-career","ctx":["GT2-career"],"title":{"en":"Job and career guides","tr":"İş ve kariyer rehberleri","fa":"راهنمای کار و مسیر شغلی"},"asks":{"en":"Guides for job seekers and employees: CVs, interviews, promotion, resigning, freelance work, apprenticeships. Sentence and note completion test the advice.","tr":"İş arayanlar ve çalışanlar için rehberler: özgeçmiş, mülakat, terfi, istifa, serbest çalışma, çıraklık. Cümle ve not tamamlama tavsiyeleri sınar.","fa":"راهنما برای کارجوها و کارمندها: رزومه، مصاحبه، ترفیع، استعفا، کار آزاد، کارآموزی حرفه‌ای. کامل کردن جمله و یادداشت توصیه‌ها را می‌سنجد."},"fields":["Keep your CV to ___ pages.","Research the company before the ___.","Give your employer written ___ when you resign.","Freelancers must keep records for ___."],"words":[{"a":"CV","b":"career summary / résumé","tr":"özgeçmiş","fa":"رزومه"},{"a":"applicant","b":"candidate / person applying","tr":"başvuran","fa":"متقاضی"},{"a":"vacancy","b":"an open job","tr":"açık pozisyon","fa":"موقعیت شغلی خالی"},{"a":"interview","b":"meeting with the employer","tr":"mülakat","fa":"مصاحبه"},{"a":"resign","b":"leave your job / hand in your notice","tr":"istifa etmek","fa":"استعفا دادن"},{"a":"notice period","b":"time between resigning and leaving","tr":"ihbar süresi","fa":"مدت اطلاع قبلی"},{"a":"promotion","b":"moving up to a higher job","tr":"terfi","fa":"ترفیع"},{"a":"freelance","b":"self-employed / working for yourself","tr":"serbest","fa":"آزادکار"},{"a":"apprenticeship","b":"training while you work","tr":"çıraklık","fa":"کارآموزی حرفه‌ای"},{"a":"references","b":"people who will recommend you","tr":"referanslar","fa":"معرف‌ها"},{"a":"salary","b":"pay / earnings","tr":"maaş","fa":"حقوق"},{"a":"recent","b":"latest / most up to date","tr":"en son","fa":"جدیدترین"}],"traps":[{"en":"Advice for different stages: \"before the interview\" and \"after the interview\" are different paragraphs.","tr":"Farklı aşamalar için tavsiyeler: \"mülakattan önce\" ve \"mülakattan sonra\" farklı paragraflardadır.","fa":"توصیه برای مرحله‌های مختلف: «قبل از مصاحبه» و «بعد از مصاحبه» در پاراگراف‌های جدا هستند."},{"en":"The gap needs a word from the text, even if a synonym feels more natural.","tr":"Boşluk metinden bir kelime ister; eş anlamlısı daha doğal gelse bile.","fa":"جای خالی کلمه‌ای از متن را می‌خواهد، حتی اگر مترادفش طبیعی‌تر به نظر برسد."}],"example":{"text":"Most employers spend less than a minute on each CV, so keep yours to two pages and put your most recent job first.","item":"Sentence: Put your most ___ job first.   (ONE WORD ONLY)","answer":"recent","why":{"en":"\"Put your most recent job first.\" Copy recent; do not change it to \"latest\".","tr":"\"En son işini en başa koy.\" recent kelimesini kopyala; \"latest\" diye değiştirme.","fa":"«جدیدترین شغلت را اول بنویس». کلمه‌ی recent را کپی کن؛ به latest تغییرش نده."}},"track":"gt","general":true,"patterns":["GT2-career"],"often":{"pattern":"GT2-career","n":18,"of":55,"label":{"en":"Comes up often in the real exam: 18 of the last 55 texts","tr":"Gerçek sınavda sık çıkar: son 55 metnin 18’inde","fa":"در آزمون واقعی زیاد می‌آید: در ۱۸ متن از ۵۵ متنِ اخیر"}}},{"id":"GT2-policy","ctx":["GT2-policy"],"title":{"en":"Workplace policies and conditions","tr":"İş yeri politikaları ve çalışma koşulları","fa":"سیاست‌ها و شرایط محیط کار"},"asks":{"en":"A page from a staff handbook: parking, dress code, leave, absence, benefits or the complaints procedure. Questions test what staff must do, by when, and who they tell.","tr":"Bir personel el kitabından bir sayfa: otopark, kıyafet kuralı, izin, devamsızlık, yan haklar ya da şikâyet prosedürü. Sorular personelin ne yapması gerektiğini, ne zamana kadar ve kime haber vereceğini sınar.","fa":"صفحه‌ای از راهنمای کارکنان: پارکینگ، قانون پوشش، مرخصی، غیبت، مزایا یا روند رسیدگی به شکایت. سؤال‌ها می‌سنجند کارکنان چه باید بکنند، تا کی و به چه کسی خبر بدهند."},"fields":["Staff must inform their ___ before 9 a.m. if they are ill.","Holiday requests need ___ weeks’ notice.","Parking permits are issued by ___.","Jeans may be worn on ___."],"words":[{"a":"entitled to","b":"have the right to","tr":"... hakkı olmak","fa":"حق داشتن"},{"a":"annual leave","b":"holiday","tr":"yıllık izin","fa":"مرخصی سالانه"},{"a":"notice","b":"warning in advance","tr":"önceden haber","fa":"اطلاع قبلی"},{"a":"sick leave","b":"time off when you are ill","tr":"hastalık izni","fa":"مرخصی استعلاجی"},{"a":"permit","b":"an official permission card","tr":"izin kartı","fa":"مجوز"},{"a":"dress code","b":"rules about clothes","tr":"kıyafet kuralları","fa":"قانون پوشش"},{"a":"casual","b":"informal / relaxed","tr":"rahat, gündelik","fa":"غیررسمی"},{"a":"grievance","b":"a formal complaint","tr":"resmî şikâyet","fa":"شکایت رسمی"},{"a":"approve","b":"agree to / sign off","tr":"onaylamak","fa":"تأیید کردن"},{"a":"allowance","b":"money paid for something","tr":"ödenek","fa":"کمک‌هزینه"},{"a":"probation","b":"a trial period","tr":"deneme süresi","fa":"دوره‌ی آزمایشی"},{"a":"in writing","b":"by email or letter","tr":"yazılı olarak","fa":"به‌صورت کتبی"}],"traps":[{"en":"Who to tell: \"your line manager\" and \"HR\" are often named for different steps.","tr":"Kime haber verilir: \"bağlı olduğun yönetici\" ve \"İK\" çoğu zaman farklı adımlar için geçer.","fa":"به چه کسی خبر بدهی: «مدیر مستقیم» و «منابع انسانی» اغلب برای مرحله‌های مختلف نام برده می‌شوند."},{"en":"Periods: \"two weeks’ notice\" and \"within two weeks\" mean different things.","tr":"Süreler: \"iki hafta önceden haber\" ile \"iki hafta içinde\" farklı şeylerdir.","fa":"مدت‌ها: «دو هفته اطلاع قبلی» با «ظرف دو هفته» فرق دارد."}],"example":{"text":"If you cannot come to work because of illness, phone your line manager before 9 a.m. on the first day. HR only needs to be told if the absence lasts more than five working days.","item":"Staff who are ill must first contact their ___.   (NO MORE THAN TWO WORDS)","answer":"line manager","why":{"en":"The line manager is told first; HR only after five working days.","tr":"Önce bağlı olunan yöneticiye haber verilir; İK’ya ancak beş iş gününden sonra.","fa":"اول به مدیر مستقیم خبر می‌دهی؛ به منابع انسانی فقط بعد از پنج روز کاری."}},"track":"gt","general":true,"patterns":["GT2-policy"],"often":{"pattern":"GT2-policy","n":11,"of":55,"label":{"en":"Comes up often in the real exam: 11 of the last 55 texts","tr":"Gerçek sınavda sık çıkar: son 55 metnin 11’inde","fa":"در آزمون واقعی زیاد می‌آید: در ۱۱ متن از ۵۵ متنِ اخیر"}}}]},"points":[{"eyebrow":{"en":"In the exam","tr":"Sınavda","fa":"در آزمون"},"head":{"en":"Short answers, then sentences","tr":"Önce kısa cevaplar, sonra cümleler","fa":"اول جواب کوتاه، بعد جمله‌ها"},"body":{"en":"Questions 15-20 are short questions about the first text: NO MORE THAN THREE WORDS AND/OR A NUMBER. Questions 21-27 are sentences about the second text: NO MORE THAN TWO WORDS AND/OR A NUMBER.","tr":"Soru 15-20 ilk metinle ilgili kısa sorulardır: NO MORE THAN THREE WORDS AND/OR A NUMBER. Soru 21-27 ikinci metinle ilgili cümlelerdir: NO MORE THAN TWO WORDS AND/OR A NUMBER.","fa":"سؤال‌های ۱۵ تا ۲۰ سؤال‌های کوتاهی درباره‌ی متن اول‌اند: NO MORE THAN THREE WORDS AND/OR A NUMBER. سؤال‌های ۲۱ تا ۲۷ جمله‌هایی درباره‌ی متن دوم‌اند: NO MORE THAN TWO WORDS AND/OR A NUMBER."}},{"eyebrow":{"en":"The method","tr":"Yöntem","fa":"روش"},"head":{"en":"Question word, heading, copy","tr":"Soru kelimesi, başlık, kopyala","fa":"کلمه‌ی پرسشی، عنوان، کپی"},"steps":[{"en":"Read the question word: how long, how much, where, when. It tells you the kind of answer.","tr":"Soru kelimesini oku: how long, how much, where, when. Cevabın türünü söyler.","fa":"کلمه‌ی پرسشی را بخوان: how long، how much، where، when. نوع جواب را می‌گوید."},{"en":"Use the headings of the text to find the right section quickly.","tr":"Doğru bölümü hızla bulmak için metnin başlıklarını kullan.","fa":"برای پیدا کردن سریع بخش درست از عنوان‌های متن استفاده کن."},{"en":"Copy the words and numbers exactly, and count them. A number counts separately from the words.","tr":"Kelimeleri ve sayıları aynen kopyala ve say. Sayı kelimelerden ayrı sayılır.","fa":"کلمه‌ها و عددها را دقیق کپی کن و بشمار. عدد جدا از کلمه‌ها حساب می‌شود."}]},{"eyebrow":{"en":"The trap","tr":"Tuzak","fa":"دام"},"head":{"en":"The number that does not fit","tr":"Uymayan sayı","fa":"عددی که جور نیست"},"body":{"en":"Work texts give many numbers: ages, distances, prices, days. Check that your number answers the question: \"how much a week\" needs the weekly amount, not the distance or the number of staff.","tr":"İş metinleri birçok sayı verir: yaşlar, mesafeler, fiyatlar, günler. Sayının soruyu cevapladığından emin ol: \"haftada ne kadar\" haftalık tutarı ister, mesafeyi ya da personel sayısını değil.","fa":"متن‌های کاری عدد زیاد دارند: سن، فاصله، قیمت، روز. مطمئن شو عددت به سؤال جواب می‌دهد: «هفته‌ای چقدر» مبلغ هفتگی را می‌خواهد، نه فاصله یا تعداد کارکنان را."}}],"example":{"eyebrow":{"en":"Worked example","tr":"Çözümlü örnek","fa":"مثال حل‌شده"},"head":{"en":"One short answer, step by step","tr":"Bir kısa cevap, adım adım","fa":"یک جواب کوتاه، قدم به قدم"},"instruction":"Answer the question. Choose NO MORE THAN THREE WORDS AND/OR A NUMBER from the text.","text":"\"The staff car park is two miles from the hotel. Parking permits cost £12 a month and are issued by the security team.\"","item":"Who gives out parking permits?","answer":"the security team","walk":[{"en":"\"Who\" asks for a person or a group.","tr":"\"Who\" bir kişi ya da grup sorar.","fa":"«who» یک نفر یا یک گروه را می‌پرسد."},{"en":"\"Issued by\" = given out by.","tr":"\"Issued by\" = tarafından verilir.","fa":"«issued by» یعنی توسط ... داده می‌شود."},{"en":"Copy three words: the security team. The numbers do not answer \"who\".","tr":"Üç kelime kopyala: the security team. Sayılar \"who\"yu cevaplamaz.","fa":"سه کلمه کپی کن: the security team. عددها به «who» جواب نمی‌دهند."}]},"quick":{"prompt":"Sentence (NO MORE THAN TWO WORDS AND/OR A NUMBER): \"Staff may take up to ___ days of unpaid leave.\" The text says \"Up to ten days of unpaid leave may be taken each year.\" What do you write?","options":["ten days","ten","each year"],"correct":1,"why":{"en":"\"days\" is printed after the gap, so the number alone fills it: ten (or 10).","tr":"\"days\" boşluktan sonra yazılı; boşluğu yalnızca sayı doldurur: ten (ya da 10).","fa":"«days» بعد از جای خالی چاپ شده، پس فقط عدد جایش را پر می‌کند: ten (یا 10)."}},"remember":{"en":"Let the question word choose the kind of answer, copy exactly, and count words and numbers.","tr":"Cevabın türünü soru kelimesi seçsin; aynen kopyala; kelimeleri ve sayıları say.","fa":"بگذار کلمه‌ی پرسشی نوع جواب را تعیین کند، دقیق کپی کن و کلمه‌ها و عددها را بشمار."},"type":"explain","id":"c-x04-r2-e-gt","course":"ielts-exams","exam":"exam-04","unit":"x04-r2"},"drill":{"type":"drill","skill":"reading","part":"General Training Reading Section 2","title":{"en":"Summer work at a hotel","tr":"Bir otelde yaz işi","fa":"کار تابستانی در یک هتل"},"timed":20,"ctx":["GT2-career","GT2-policy"],"texts":[{"title":"Summer work at the Glenmoor Lodge Hotel: a guide for seasonal staff","kind":"seasonal work guide","body":"Every summer we take on around forty extra staff to help in our restaurant, bar, kitchen and housekeeping teams. This guide answers the questions that new seasonal staff ask most often.\n\nContracts\nSeasonal contracts run from June to September. The minimum contract is eight weeks, and we cannot accept anyone for a shorter period, as training new staff takes time. Most people stay for the whole season, and many return the following year.\n\nBefore you start\nEveryone must complete our online induction before their first shift. Bar staff must be at least 18 years old. Kitchen staff need a food hygiene certificate; if you do not have one, you can take the course online, and we will refund the cost after your first month with us.\n\nAccommodation\nStaff rooms are available in the cottages behind the hotel. Each room is shared by two people, and there is a shared kitchen in each cottage. If you choose to live on site, £65 a week is deducted from your pay to cover rent, heating and electricity.\n\nUniforms\nUniforms are provided free of charge. Collect yours from the housekeeping office on your first morning, and return it there at the end of your contract. Black shoes are not provided, so please bring your own.\n\nGetting to work\nThe hotel is eight miles from the nearest town and there is no public bus. Staff without a car can use the minibus, which runs to and from the town at the start and end of every shift at no cost.\n\nPay\nWages are paid directly into your bank account every other Friday. You will receive an online payslip on the same day. Tips are shared equally between all restaurant and bar staff at the end of each month."},{"title":"Glenmoor Lodge Hotel: staff leave guidelines","kind":"staff guidelines","body":"These guidelines apply to all permanent staff. Seasonal staff should speak to their manager, as different rules apply to short contracts.\n\nPaid leave\nFull-time staff are entitled to 28 days of paid leave per year, including public holidays. Part-time staff receive the same amount in proportion to the hours they work. The leave year runs from January to December.\n\nRequesting leave\nRequests must be made at least four weeks in advance through the staff portal. Paper forms are no longer accepted. Your manager will reply within five working days. Requests are generally approved in the order in which they are received, so it is worth planning ahead, especially for the summer. If two people in the same team ask for the same dates, the manager may ask one of them to choose another week.\n\nBusy periods\nBecause the hotel is at its busiest when families are on holiday, leave is not normally allowed during the school holidays in July and August, except in special circumstances. Requests for this period are considered individually by the general manager.\n\nUnused leave\nWe encourage everyone to take their full holiday entitlement. However, if you are unable to do so, up to five unused days can be carried over into the following year. These days must be taken by the end of March, or they will be lost.\n\nSickness\nIf you are ill and cannot come to work, you must phone your line manager before your shift starts. Sending a text message or an email is not enough. For any period of sickness lasting more than seven days, you will need to provide a note from your doctor.\n\nOther types of leave\nStaff may also request unpaid leave, or time off to care for a family member. These requests are discussed with the HR team, who will explain the options and help you to plan your time away from work."}],"groups":[{"text":0,"instruction":"Questions 15-20. Answer the questions below. Choose NO MORE THAN THREE WORDS AND/OR A NUMBER from the text for each answer. Write your answers in boxes 15-20 on your answer sheet.","qtype":"short-answer","questions":[{"n":15,"kind":"gap","prompt":"What is the shortest contract that the hotel offers? ___","accept":["eight weeks","8 weeks"],"limit":3,"evidence":"The minimum contract is eight weeks","why":{"en":"\"The minimum contract is eight weeks\": minimum = shortest.","tr":"\"En kısa sözleşme sekiz hafta\": minimum = shortest.","fa":"«حداقل قرارداد هشت هفته است»: minimum یعنی کوتاه‌ترین."},"trap":["TR-limit","TR-paraphrase"]},{"n":16,"kind":"gap","prompt":"What must kitchen staff have before they start? ___","accept":["food hygiene certificate"],"limit":3,"evidence":"Kitchen staff need a food hygiene certificate","why":{"en":"\"Kitchen staff need a food hygiene certificate.\" Leave out \"a\" to stay within three words.","tr":"\"Mutfak personelinin gıda hijyeni sertifikası olmalı.\" Üç kelimede kalmak için \"a\"yı çıkar.","fa":"«کارکنان آشپزخانه گواهی بهداشت مواد غذایی لازم دارند». برای ماندن در سه کلمه «a» را حذف کن."},"trap":["TR-limit","TR-paraphrase"]},{"n":17,"kind":"gap","prompt":"How much is taken from the weekly pay of staff who live on site? ___","accept":["£65","65"],"limit":3,"evidence":"£65 a week is deducted from your pay","why":{"en":"\"£65 a week is deducted from your pay\": deducted = taken. The other numbers are distances and dates.","tr":"\"Maaşından haftada 65 £ kesilir\": deducted = taken. Diğer sayılar mesafe ve tarih.","fa":"«هفته‌ای ۶۵ پوند از حقوقت کم می‌شود»: deducted یعنی taken. بقیه‌ی عددها فاصله و تاریخ‌اند."},"trap":["TR-paraphrase"]},{"n":18,"kind":"gap","prompt":"Where do new staff collect their uniform? ___","accept":["the housekeeping office","housekeeping office"],"limit":3,"evidence":"Collect yours from the housekeeping office","why":{"en":"\"Collect yours from the housekeeping office on your first morning.\"","tr":"\"İlk sabahında kendi üniformanı kat hizmetleri ofisinden al.\"","fa":"«صبح روز اول لباست را از دفتر خانه‌داری بگیر»."},"trap":["TR-limit","TR-paraphrase"]},{"n":19,"kind":"gap","prompt":"What can staff without a car use to get to the hotel? ___","accept":["the minibus","minibus"],"limit":3,"evidence":"Staff without a car can use the minibus","why":{"en":"There is no public bus; staff \"can use the minibus\" at no cost.","tr":"Toplu otobüs yok; personel ücretsiz olarak \"minibüsü kullanabilir\".","fa":"اتوبوس عمومی نیست؛ کارکنان «می‌توانند رایگان از مینی‌بوس استفاده کنند»."},"trap":["TR-limit","TR-paraphrase"]},{"n":20,"kind":"gap","prompt":"How often are wages paid? ___","accept":["every other Friday"],"limit":3,"evidence":"every other Friday","why":{"en":"\"Wages are paid directly into your bank account every other Friday.\" Three words.","tr":"\"Ücretler iki haftada bir cuma doğrudan banka hesabına yatırılır.\" Üç kelime.","fa":"«دستمزد هر دو هفته یک بار، جمعه، مستقیم به حساب بانکی واریز می‌شود». سه کلمه."},"trap":["TR-limit","TR-paraphrase"]}]},{"text":1,"instruction":"Questions 21-27. Complete the sentences below. Choose NO MORE THAN TWO WORDS AND/OR A NUMBER from the text for each answer. Write your answers in boxes 21-27 on your answer sheet.","qtype":"sentence","questions":[{"n":21,"kind":"gap","prompt":"Full-time staff have ___ days of paid leave a year, including public holidays.","accept":["28"],"limit":2,"evidence":"entitled to 28 days of paid leave","why":{"en":"\"Entitled to 28 days of paid leave per year, including public holidays.\"","tr":"\"Resmî tatiller dahil yılda 28 gün ücretli izin hakkı.\"","fa":"«حق ۲۸ روز مرخصی با حقوق در سال، با تعطیلات رسمی»."},"trap":["TR-limit"]},{"n":22,"kind":"gap","prompt":"Leave must be requested at least ___ before it starts.","accept":["four weeks","4 weeks"],"limit":2,"evidence":"at least four weeks in advance","why":{"en":"\"At least four weeks in advance\": in advance = before.","tr":"\"En az dört hafta önceden\": in advance = before.","fa":"«دست‌کم چهار هفته از قبل»: in advance یعنی before."},"trap":["TR-limit","TR-paraphrase"]},{"n":23,"kind":"gap","prompt":"Requests for leave are made through the ___.","accept":["staff portal"],"limit":2,"evidence":"through the staff portal","why":{"en":"\"Through the staff portal. Paper forms are no longer accepted.\"","tr":"\"Personel portalı üzerinden. Kâğıt formlar artık kabul edilmiyor.\"","fa":"«از طریق پرتال کارکنان. فرم کاغذی دیگر پذیرفته نمی‌شود»."},"trap":["TR-limit","TR-paraphrase"]},{"n":24,"kind":"gap","prompt":"Staff cannot normally take leave during the ___ in July and August.","accept":["school holidays"],"limit":2,"evidence":"during the school holidays in July and August","why":{"en":"\"Leave is not normally allowed during the school holidays in July and August.\"","tr":"\"Temmuz ve ağustostaki okul tatillerinde normalde izin verilmez.\"","fa":"«در تعطیلات مدرسه در ژوئیه و اوت معمولاً مرخصی داده نمی‌شود»."},"trap":["TR-limit","TR-paraphrase"]},{"n":25,"kind":"gap","prompt":"No more than ___ unused days can be carried over.","accept":["five","5"],"limit":2,"evidence":"up to five unused days can be carried over","why":{"en":"\"Up to five unused days can be carried over\": up to = no more than.","tr":"\"En fazla beş kullanılmamış gün devredilebilir\": up to = no more than.","fa":"«حداکثر پنج روزِ استفاده‌نشده منتقل می‌شود»: up to یعنی no more than."},"trap":["TR-limit","TR-paraphrase"]},{"n":26,"kind":"gap","prompt":"Days that are carried over must be used by the end of ___.","accept":["March"],"limit":2,"evidence":"must be taken by the end of March","why":{"en":"\"These days must be taken by the end of March, or they will be lost.\"","tr":"\"Bu günler mart sonuna kadar kullanılmalı, yoksa yanar.\"","fa":"«این روزها باید تا آخر مارس استفاده شوند، وگرنه از بین می‌روند»."},"trap":["TR-limit","TR-paraphrase"]},{"n":27,"kind":"gap","prompt":"Staff who are ill must phone their ___ before their shift begins.","accept":["line manager"],"limit":2,"evidence":"you must phone your line manager","why":{"en":"\"You must phone your line manager before your shift starts.\" A text or email is not enough.","tr":"\"Vardiyan başlamadan önce bağlı olduğun yöneticiyi aramalısın.\" Mesaj ya da e-posta yetmez.","fa":"«باید قبل از شروع شیفت به مدیر مستقیمت زنگ بزنی». پیامک یا ایمیل کافی نیست."},"trap":["TR-limit","TR-paraphrase"]}]}],"id":"c-x04-r2-d-gt","course":"ielts-exams","exam":"exam-04","unit":"x04-r2"},"exit":{"type":"exit","items":[{"tests":"word","point":1,"prompt":"\"£20 is deducted from your pay.\" This means £20 is...","options":["taken out of your wages","added to your wages","paid to you in cash"],"correct":0,"why":{"en":"Deducted = taken away from a total.","tr":"Deducted = bir toplamdan düşülen.","fa":"deducted یعنی از مجموع کم‌شده."}},{"tests":"paraphrase","point":2,"prompt":"Which phrase means \"at least four weeks before\"?","options":["within four weeks","after four weeks","no less than four weeks in advance"],"correct":2,"why":{"en":"\"In advance\" = before; \"no less than\" = at least.","tr":"\"In advance\" = önceden; \"no less than\" = en az.","fa":"«in advance» یعنی از قبل؛ «no less than» یعنی دست‌کم."}},{"tests":"method","point":2,"prompt":"NO MORE THAN THREE WORDS AND/OR A NUMBER. Which answer breaks the limit?","options":["the staff entrance","a new staff uniform","£12 a week"],"correct":1,"why":{"en":"\"a new staff uniform\" is four words; the others are three words, or a number and two words.","tr":"\"a new staff uniform\" dört kelime; diğerleri üç kelime ya da bir sayı ve iki kelime.","fa":"«a new staff uniform» چهار کلمه است؛ بقیه سه کلمه یا یک عدد و دو کلمه‌اند."}},{"tests":"trap","point":3,"prompt":"Question: \"How much does a staff room cost per week?\" The text says \"The cottages are 2 miles away; rooms cost £70 a week; 12 staff live there.\" What do you write?","options":["£70","2 miles","12"],"correct":0,"why":{"en":"\"How much... per week\" needs the weekly price; the other numbers answer different questions.","tr":"\"Haftada ne kadar\" haftalık fiyatı ister; diğer sayılar başka soruların cevabı.","fa":"«هفته‌ای چقدر» قیمت هفتگی را می‌خواهد؛ عددهای دیگر جواب سؤال‌های دیگرند."}}],"id":"c-x04-r2-x-gt","course":"ielts-exams","exam":"exam-04","unit":"x04-r2"}}}; })(globalThis.IELTS_EXAMS = globalThis.IELTS_EXAMS || {});
